mapper.select:
SELECT * FROM selected_stock
WHERE strategy_code = #{strategyCode}
AND selection_date = #{selectionDate}
ORDER BY created_at DESC

SELECT * FROM selected_stock
WHERE strategy_code = #{strategyCode}
AND selection_date = (
    SELECT MAX(selection_date)
    FROM selected_stock
    WHERE strategy_code = #{strategyCode}
)
ORDER BY stock_code

